# New hypothesis: maybe specific value combinations cause insertion or deletion
demo_in = [6, 6, 3, 3, 3, 8, 8, 5, 4, 4, 0, 2, 5, 6, 0, 6, 8, 0, 4, 4, 6, 8, 4, 6, 1, 5, 1, 2, 3, 2]
demo_out = [4, 4, 8, 3, 3, 3, 3, 8, 0, 4, 6, 2, 2, 3, 1, 6, 4, 1, 4, 6, 6, 4, 1, 6, 9, 5, 3, 6]

# Let me try a different approach: what if the transformation is position-independent
# and just maps certain values to other values based on some rule?

# Let me count what input values become what output values
from collections import Counter

value_mapping = {}
for i in range(30):
    out_val = demo_out[i]
    in_val = demo_in[i]

    if out_val != in_val:
        if in_val not in value_mapping:
            value_mapping[in_val] = Counter()
        value_mapping[in_val][out_val] += 1

print("Value transformation counts (input -> output):")
for in_val, out_counts in value_mapping.items():
    for out_val, count in out_counts.items():
        print(f"  {in_val} -> {out_val}: {count} times")

# Now also track unchanged values
print("\nUnchanged values:")
for i in range(30):
    if demo_in[i] == demo_out[i]:
        print(f"  {demo_in[i]} (pos {i})")

