        elif block == b90:
            rname = '90°'
        elif block == b180:
            rname = '180°'
        else:
            rname = '???'

        print(f"Block ({r},{c}): {rname}")

def get_block_tuple(r, c):
    return tuple(tuple(x for x in row) for row in output_grid[3*r:3*r+3, 3*c:3*c+3])

inp_tuple = tuple(tuple(row) for row in input_grid)
b90 = tuple(tuple(row) for row in is_90cw(input_grid))
b180 = tuple(tuple(row) for row in is_180(input_grid))
b0 = inp_tuple

for r in range(3):
    for c in range(3):
        block = get_block_tuple(r, c)
        if block == b0:
            rname = '0°'
        elif block == b90:
            rname = '90°'
        elif block == b180:
            rname = '180°'
        else:
            rname = '???'

        print(f"Block ({r},{c}): {rname}")

# Verify the pattern by checking against demo
input_no_in = [[7, 6, 7], [2, 7, 6], [1, 2, 7]]

def rot180(g):
    return [[g[2][2], g[2][1], g[2][0]],
            [g[1][2], g[1][1], g[1][0]],
            [g[0][2], g[0][1], g[0][0]]]

def rot90(g):
    return [[g[2][0], g[2][1], g[2][2]],
            [g[1][0], g[1][1], g[1][2]],
            [g[0][0], g[0][1], g[0][2]]]

def flip_h(g):
    return [[g[0][2], g[0][1], g[0][0]],
            [g[1][2], g[1][1], g[1][0]],
            [g[2][2], g[2][1], g[2][0]]]

inp = input_no_in
r180 = rot180(inp)
r90 = rot90(inp)
fh = flip_h(inp)

# Build using same logic
output_rows_demo = []
for r_block in range(3):
    for r_out in range(3):
        row = []
        for c_block in range(3):
            if r_block % 2 == 0:
                if c_block % 2 == 1:
                    block = r90
                else:
                    block = r180
            else:
                if c_block % 2 == 1:
                    block = inp
                else:
                    block = fh
            row.extend(block[r_out])
        output_rows_demo.append(row)

