def rot180(g):
    return [[g[2][2], g[2][1], g[2][0]],
            [g[1][2], g[1][1], g[1][0]],
            [g[0][2], g[0][1], g[0][0]]]

def rot90(g):
    return [[g[2][0], g[2][1], g[2][2]],
            [g[1][0], g[1][1], g[1][2]],
            [g[0][0], g[0][1], g[0][2]]]

def flip_h(g):
    return [[g[0][2], g[0][1], g[0][0]],
            [g[1][2], g[1][1], g[1][0]],
            [g[2][2], g[2][1], g[2][0]]]

r180 = rot180(inp)
r90 = rot90(inp)
fh = flip_h(inp)

# Build 9x9 output
output_rows = []
for r_block in range(3):
    for r_out in range(3):
        row = []
        for c_block in range(3):
            if r_block % 2 == 0:
                if c_block % 2 == 1:
                    block = r90
                else:
                    block = r180
            else:
                if c_block % 2 == 1:
                    block = inp
                else:
